# Edit this file, then run: Rscript scripts/build_boba_app.R
# Base R graphics keeps browser downloads small. All amounts are AUD.
library(shiny)
library(bslib)
blue <- "#4682B4"
coral <- "#F08080"
red <- "#B22222"
ui <- page_fluid(
  theme=bs_theme(version=5, primary="#006DAE", base_font=font_collection("Fira Sans", "Arial", "sans-serif")),
  tags$head(tags$script(HTML('$(document).on("shiny:connected", () => { document.body.classList.add("first-three", "sample-view"); Shiny.addCustomMessageHandler("bobaView", view => { document.body.classList.toggle("first-three", view !== "ci" && view !== "clt"); document.body.classList.toggle("sample-view", view === "sample"); }); Shiny.addCustomMessageHandler("sliderGrid", count => setTimeout(() => { const slider = $("#n").data("ionRangeSlider"); if (slider) slider.update({grid_num:count, grid_snap:true}); }, 0)); window.parent.postMessage({bobaReady:true},location.origin); }); function showBobaTabs(names) { const visible = new Set(names.split(",").map(name => name.trim())); document.querySelectorAll("#view > li > a[data-value]").forEach(link => { link.parentElement.style.display = visible.has(link.dataset.value) ? "" : "none"; }); } window.addEventListener("message", function(event) { if(event.origin !== window.location.origin) return; if (typeof event.data?.bobaTabs === "string") showBobaTabs(event.data.bobaTabs); if (["sample", "means", "sampling", "ci", "clt"].includes(event.data?.bobaTab)) Shiny.setInputValue("requestedTab", event.data.bobaTab, {priority:"event"}); if (["intro", "intro-se", "full", "clt"].includes(event.data?.bobaMode)) { document.body.classList.toggle("clt-mode", event.data.bobaMode === "clt"); document.body.classList.toggle("intro-mode", event.data.bobaMode === "intro" || event.data.bobaMode === "intro-se"); document.body.classList.toggle("mode-intro", event.data.bobaMode === "intro"); Shiny.setInputValue("requestedMode", event.data.bobaMode, {priority:"event"}); } });')),
    tags$style(HTML('
      body {color:#171717;background:white;font-size:16px;padding:4px 12px;}
      .card {box-shadow:none;} .card-header {background:white;}
      .controls {display:grid;grid-template-columns:minmax(150px,1.7fr) repeat(3,minmax(110px,.8fr)) minmax(125px,.9fr);gap:12px;align-items:center;}
      .form-group {margin-bottom:0;} .actions {display:flex;flex-direction:column;gap:6px;min-width:0;} .actions .btn {white-space:nowrap;padding:8px 12px;}
      .bslib-value-box {border-left:4px solid #4682B4;background:#f4f7fa!important;color:#171717!important;}
      .bslib-value-box .value-box-title {font-size:15px!important;}
      .bslib-value-box .value-box-value {font-size:25px!important;}
      .bslib-value-box .value-box-area {padding:8px 14px!important;}
      .cards {margin-bottom:0;} .bslib-value-box {min-height:70px!important;height:70px!important;} .value-box-grid {padding:0!important;} .card-body {gap:6px;} .note {font-size:14px;color:#555;margin:4px 0;}
      .header-stat {min-width:0;}
      #samplePlot {height:calc(100vh - 315px)!important;}
      #meansPlot {height:calc(100vh - 315px)!important;}
      #samplingPlot {height:calc(100vh - 315px)!important;}
      #ciPlot {height:calc(100vh - 280px)!important;}
      #ciSummary {text-align:right;}
      .nav-link {color:#444;} .nav-link.active {color:#006DAE!important;font-weight:bold;}
      body.intro-mode .header-n {display:none!important;}
      body.intro-mode.first-three .controls {grid-template-columns:minmax(150px,1.7fr) repeat(2,minmax(110px,.8fr)) minmax(125px,.9fr);}
      body.mode-intro .header-se {display:none!important;}
      body.first-three.sample-view .header-se {display:none!important;}
      body.first-three.sample-view .controls {grid-template-columns:minmax(150px,1.7fr) repeat(2,minmax(110px,.8fr)) minmax(125px,.9fr);}
      body.mode-intro.first-three .controls {grid-template-columns:minmax(150px,1.7fr) minmax(110px,.8fr) minmax(125px,.9fr);}
      body.intro-mode.first-three.sample-view .controls {grid-template-columns:minmax(150px,1.7fr) minmax(110px,.8fr) minmax(125px,.9fr);}
      body.first-three .advanced-control {display:none!important;}
      body:not(.first-three) .header-stat {display:none!important;}
      body:not(.first-three) .controls {grid-template-columns:1.7fr 1fr 1fr 1.3fr;}
      body.intro-mode #samplePlot {height:calc(100vh - 175px)!important;min-height:260px;}
      body.intro-mode #meansPlot {height:calc(100vh - 175px)!important;min-height:260px;}
      body.first-three #samplingPlot {height:calc(100vh - 175px)!important;min-height:260px;}
      body.clt-mode .controls {display:none!important;}
      .clt-controls {display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin:4px 0 8px;}
      .clt-controls .form-group {min-width:270px;flex:1;}
      .clt-controls .btn {white-space:nowrap;}
      .clt-stats {font-size:16px;margin:4px 0;color:#171717;}
      #cltPlot {height:calc(100vh - 190px)!important;min-height:280px;}
    '))),
  navset_card_tab(id="view", selected="sample",
    header=card_body(padding=c("8px", "16px"), fill=FALSE,
      div(class="controls",
        sliderInput("n", "Cups per sample (n)", min=5, max=30, value=5, step=5),
        div(class="header-stat header-n", uiOutput("headerN")),
        div(class="header-stat", uiOutput("introMean")),
        div(class="header-stat header-se", uiOutput("introSE")),
        div(class="advanced-control", numericInput("mu", "Population mean (AUD)", value=8, min=.01, step=.1)),
        div(class="advanced-control", numericInput("sigma", "Population SD (AUD)", value=3, min=.01, step=.1)),
        div(class="actions", actionButton("draw", "Draw sample", class="btn-primary"), actionButton("reset", "Reset")))),
    nav_panel("Sample", value="sample", plotOutput("samplePlot", height="220px")),
    nav_panel("Sample means", value="means", plotOutput("meansPlot", height="320px")),
    nav_panel("Sampling Distribution", value="sampling", plotOutput("samplingPlot", height="270px")),
    nav_panel("CLT: skewed population", value="clt",
      div(class="clt-controls",
        sliderInput("cltN", "Cups per sample (n)", min=5, max=100, value=5, step=5),
        actionButton("cltDraw", "Draw 1 sample", class="btn-primary"),
        actionButton("cltDraw100", "Draw 100 samples"),
        actionButton("cltReset", "Reset")),
      div(class="clt-stats", textOutput("cltStats", inline=TRUE)),
      plotOutput("cltPlot", height="300px"),
      div(class="note", "Right-skewed prices are simulated. Changing n starts a fresh set of samples.")),
    nav_panel("Confidence Interval", value="ci", uiOutput("ciSummary"), plotOutput("ciPlot", height="260px"),
      div(class="note", "95% t interval: sample mean ± t(0.975, n − 1) × s / √n.")))
)
server <- function(input, output, session) {
  observeEvent(input$requestedTab, nav_select("view", selected=input$requestedTab, session=session))
  observeEvent(input$view, {
    session$sendCustomMessage("bobaView", input$view)
  })
  observeEvent(input$requestedMode, {
    if (input$requestedMode == "clt") return()
    if (input$requestedMode %in% c("intro", "intro-se")) {
      updateSliderInput(session, "n", min=5, max=30, step=5,
        value=5 + 5 * floor((min(isolate(input$n), 30) - 5) / 5))
      session$sendCustomMessage("sliderGrid", 5)
    } else {
      updateSliderInput(session, "n", min=25, max=200, step=25,
        value=25 * max(1, round(isolate(input$n) / 25)))
      session$sendCustomMessage("sliderGrid", 7)
    }
  })
  # Retain raw prices and statistics for every draw in this session.
  history <- reactiveVal(list())
  latest <- reactive({ req(length(history()) > 0); tail(history(), 1)[[1]]$prices })
  observeEvent(list(input$mu, input$sigma, input$reset), {
    history(list())
  }, priority=10)
  observeEvent(input$draw, {
    req(is.finite(input$mu), is.finite(input$sigma), input$sigma > 0)
    x <- rnorm(input$n, input$mu, input$sigma)
    se <- sd(x)/sqrt(length(x))
    record <- list(prices=x, n=length(x), mean=mean(x), sd=sd(x), se=se,
      ci=mean(x)+c(-1,1)*qt(.975,length(x)-1)*se)
    history(append(history(), list(record)))
  })
  sampleStats <- reactive({
    req(length(history()) > 0)
    tail(history(), 1)[[1]]
  })
  money <- function(x) sprintf("$%.2f", x)
  output$headerN <- renderUI({
    value <- if (length(history()) == 0) "—" else as.character(sampleStats()$n)
    value_box("Last draw n", value, theme="light", fill=FALSE)
  })
  output$introMean <- renderUI({
    value <- if (length(history()) == 0) "—" else money(sampleStats()$mean)
    value_box("Sample mean (x̄)", value, theme="light", fill=FALSE)
  })
  output$introSE <- renderUI({
    value <- if (length(history()) == 0) "—" else money(sampleStats()$se)
    value_box("Estimated SE (s / √n)", value, theme="light", fill=FALSE)
  })
  # The deck moves this app between slides. Its iframe can briefly report a
  # near-zero size, so keep the R graphics device large enough for its margins.
  plotWidth <- function(id) function() {
    width <- session$clientData[[paste0("output_", id, "_width")]]
    if (is.null(width) || !is.finite(width)) width <- 0
    max(640, width)
  }
  plotHeight <- function(id) function() {
    height <- session$clientData[[paste0("output_", id, "_height")]]
    if (is.null(height) || !is.finite(height)) height <- 0
    max(240, height)
  }
  plotStyle <- function() par(mar=c(4.2,4.2,1.2,1), mgp=c(2.6,.7,0), cex=1.25, fg="#737373", col.axis="#171717", col.lab="#171717", family="sans")
  output$samplePlot <- renderPlot({
    validate(need(length(history()) > 0, "Draw a sample to see its prices."))
    plotStyle(); x <- latest(); s <- sampleStats()
    bins <- hist(x, breaks="Scott", plot=FALSE)
    width <- diff(bins$breaks)[1]
    grid <- seq(min(bins$breaks), max(bins$breaks), length.out=500)
    fitted <- dnorm(grid,s$mean,s$sd)*length(x)*width
    plot(bins, freq=TRUE, col=adjustcolor(blue,.65), border="white", main="",
      xlab="Boba price (AUD)", ylab="Count", ylim=c(0,max(bins$counts,fitted)))
    lines(grid, fitted, col=blue, lwd=3)
  }, width=plotWidth("samplePlot"), height=plotHeight("samplePlot"), res=110)
  output$meansPlot <- renderPlot({
    validate(need(length(history()) > 0, "Draw a sample to see its mean."))
    plotStyle(); par(mar=c(4.2,6.5,.6,1))
    means <- vapply(history(), `[[`, numeric(1), "mean")
    k <- length(means); ids <- seq_len(k)
    colours <- ifelse(ids==k, blue, adjustcolor(blue,.3))
    # Zoom the price axis to show variation between the retained sample means.
    limits <- extendrange(c(means, input$mu), f=.2)
    centres <- barplot(means, col=colours, border=NA, ylim=limits, xpd=FALSE,
      xlab="Draw", ylab="", axes=FALSE)
    mtext("Sample mean\nprice", side=2, line=2.3, las=1, cex=.8)
    labelled <- if(k<=20) ids else unique(round(seq(1,k,length.out=10)))
    axis(1, at=centres[labelled], labels=labelled)
    axis(2)
    abline(h=input$mu, col=coral, lty=2, lwd=3)

  }, width=plotWidth("meansPlot"), height=plotHeight("meansPlot"), res=110)
  output$samplingPlot <- renderPlot({
    req(is.finite(input$mu), is.finite(input$sigma), input$sigma > 0)
    plotStyle(); draws <- history(); k <- length(draws)
    limits <- input$mu + c(-4,4) * input$sigma
    grid <- seq(limits[1],limits[2],length.out=600)
    population <- dnorm(grid,input$mu,input$sigma)
    curves <- if(k>0) vapply(draws,function(s) dnorm(grid,input$mu,s$se), numeric(length(grid))) else NULL
    plot(grid,population,type="n",yaxt="n",ylab="",bty="n",
      xlab="Boba price or sample mean (AUD)",ylim=c(0,max(population,curves)*1.15))
    if(k>1) matlines(grid,curves[,seq_len(k-1),drop=FALSE],col=adjustcolor(blue,.3),lty=1,lwd=1.5)
    if(k>0) lines(grid,curves[,k],col=blue,lwd=3)
    lines(grid,population,col=coral,lwd=3)
    labels <- sprintf("Population prices (μ = %s, σ = %s)",money(input$mu),money(input$sigma))
    colours <- coral; widths <- 3
    if(k>1) {
      labels <- c(labels,"Earlier estimated sampling curves")
      colours <- c(colours,adjustcolor(blue,.4)); widths <- c(widths,1.5)
    }
    if(k>0) {
      labels <- c(labels,paste0("Latest: n = ",draws[[k]]$n,", estimated SE = ",money(draws[[k]]$se)))
      colours <- c(colours,blue); widths <- c(widths,3)
    }
    legend("topright",labels,lty=1,col=colours,lwd=widths,bty="n",cex=.8)
  }, width=plotWidth("samplingPlot"), height=plotHeight("samplingPlot"), res=110)
  output$ciSummary <- renderUI({
    if(length(history()) == 0) return(p("Draw a sample to estimate the population mean."))
    captures <- vapply(history(),function(d) d$ci[1]<=input$mu && d$ci[2]>=input$mu,logical(1))
    p(sprintf("%s miss μ | %s contain μ | %.1f%% contain μ",
      sum(!captures),sum(captures),100*mean(captures)))
  })
  output$ciPlot <- renderPlot({
    validate(need(length(history()) > 0, "Draw a sample to see its confidence interval."))
    plotStyle(); par(mar=c(4.2, 12, 1.2, 1))
    draws <- history(); k <- length(draws)
    means <- vapply(draws, `[[`, numeric(1), "mean")
    lower <- vapply(draws,function(d) d$ci[1],numeric(1))
    upper <- vapply(draws,function(d) d$ci[2],numeric(1))
    ids <- seq_len(k)
    captures <- lower<=input$mu & upper>=input$mu
    colours <- ifelse(captures,
      ifelse(ids==k,blue,adjustcolor(blue,.3)),
      ifelse(ids==k,red,adjustcolor(red,.55)))
    plot(NA,xlim=extendrange(c(lower,upper,input$mu),f=.1),ylim=c(.5,k+.8),
      yaxt="n",ylab="",xlab="Mean boba price (AUD)",bty="n")
    abline(v=input$mu,lty=2,col=coral,lwd=3)
    segments(lower,ids,upper,ids,col=colours,lwd=ifelse(ids==k,4,2))
    points(means,ids,pch=19,col=colours,cex=ifelse(ids==k,1.2,.8))
    legend(x=grconvertX(.01, from="ndc", to="user"), y=par("usr")[4],
      xjust=0, yjust=1, xpd=NA,
      legend=c(paste("Population mean",money(input$mu)),"Earlier draws (contain μ)","Latest draw","Misses μ"),
      col=c(coral,adjustcolor(blue,.3),colours[k],red),lty=c(2,1,1,1),
      pch=c(NA,19,19,19),pt.cex=c(NA,.8,1.2,.8),lwd=c(3,2,4,2),bty="n",cex=.8)
  }, width=plotWidth("ciPlot"), height=plotHeight("ciPlot"), res=110)

  # A separate CLT demonstration: skewed prices and their repeated sample means.
  # The lognormal population has mean $8; its skew makes the change in shape visible.
  cltLogSD <- 0.9
  cltLogMean <- log(8) - cltLogSD^2/2
  cltHistory <- reactiveVal(list(means=numeric(), latest=NULL))
  observeEvent(list(input$cltN, input$cltReset), {
    cltHistory(list(means=numeric(), latest=NULL))
  })
  drawClt <- function(count) {
    n <- isolate(input$cltN)
    samples <- replicate(count, rlnorm(n, cltLogMean, cltLogSD), simplify=FALSE)
    old <- isolate(cltHistory())
    cltHistory(list(means=c(old$means, vapply(samples, mean, numeric(1))),
      latest=tail(samples, 1)[[1]]))
  }
  observeEvent(input$cltDraw, drawClt(1))
  observeEvent(input$cltDraw100, drawClt(100))
  output$cltStats <- renderText({
    h <- cltHistory()
    if (length(h$means) == 0) return("Draw samples to compare individual prices with sample means.")
    x <- h$latest
    sprintf("%d sample means drawn  |  Latest mean: %s  |  Latest estimated SE: %s (s / √n)",
      length(h$means), money(mean(x)), money(sd(x)/sqrt(length(x))))
  })
  output$cltPlot <- renderPlot({
    h <- cltHistory()
    par(mfrow=c(1,2), mar=c(4.2,4.3,2.3,1), mgp=c(2.5,.7,0),
      cex=1.05, fg="#737373", col.axis="#171717", col.lab="#171717", family="sans")
    priceGrid <- seq(0,45,length.out=500)
    plot(priceGrid, dlnorm(priceGrid,cltLogMean,cltLogSD), type="l", lwd=3,
      col=coral, bty="n", main="Right-skewed population",
      xlab="Individual boba price (AUD)", ylab="Density")
    abline(v=8, col="#737373", lty=2)
    if (!is.null(h$latest)) rug(h$latest[h$latest<=45], col=adjustcolor(blue,.55), ticksize=.07)
    if (length(h$means) < 2) {
      plot(NA, xlim=c(0,25), ylim=c(0,1), yaxt="n", ylab="", bty="n",
        main="Means from repeated samples", xlab="Sample mean price (AUD)")
      abline(v=8, col="#737373", lty=2)
      if (length(h$means) == 1) points(h$means, .5, pch=19, col=blue, cex=1.5)
    } else {
      means <- h$means
      hist(means, breaks=max(5,min(24,ceiling(sqrt(length(means))))), freq=FALSE,
        col=adjustcolor(blue,.7), border="white", bty="n",
        main="Means from repeated samples", xlab="Sample mean price (AUD)",
        ylab="Density")
      abline(v=8, col="#737373", lty=2, lwd=2)
      points(tail(means,1), 0, pch=17, col=blue, cex=1.3)
    }
  }, width=plotWidth("cltPlot"), height=plotHeight("cltPlot"), res=110)
}
shinyApp(ui, server)
